import{_ as a,o as t,c as s,a3 as i}from"./chunks/framework.DAK02U1-.js";const g=JSON.parse('{"title":"Versions and releases","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Versions and releases | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/reference/releases"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/reference/releases"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/reference/releases"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/reference/releases"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/reference/releases"}]]},"headers":[],"relativePath":"xclang/reference/releases.md","filePath":"en/xclang/reference/releases.md","lastUpdated":1791227177000}'),r={name:"xclang/reference/releases.md"};function l(n,e,o,d,h,c){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="versions-and-releases" tabindex="-1">Versions and releases <a class="header-anchor" href="#versions-and-releases" aria-label="Permalink to &quot;Versions and releases&quot;">​</a></h1><h2 id="versions" tabindex="-1">Versions <a class="header-anchor" href="#versions" aria-label="Permalink to &quot;Versions&quot;">​</a></h2><p>A release is tagged <code>&lt;llvm version&gt;.&lt;revision&gt;</code>: <code>23.1.2.1</code> is the first build of LLVM 23.1.2, <code>23.1.2.6</code> the sixth. The version orders the way conda, Bazel and CMake order versions, and says which LLVM it is.</p><p>Nothing published is ever replaced. A fix to a release, even one that only rebuilds it, is the next revision; the workflow that drafts a release refuses a version that exists. So a version, and the sha256 of each of its archives, means one thing forever, which is what pinning by digest (Bazel&#39;s <code>versions.bzl</code>, CMake&#39;s download) relies on.</p><p>The conda package&#39;s version is the release&#39;s; its build number counts packaging fixes of that release, each the same toolchain packaged again. The Bazel module&#39;s version is the release&#39;s.</p><p>What each release changed is in the <a href="https://github.com/clice-io/xclang/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG</a>.</p><h2 id="assets" tabindex="-1">Assets <a class="header-anchor" href="#assets" aria-label="Permalink to &quot;Assets&quot;">​</a></h2><p>Every <a href="https://github.com/clice-io/xclang/releases" target="_blank" rel="noreferrer">GitHub release</a> has the same 17 assets:</p><table tabindex="0"><thead><tr><th>asset</th><th></th><th>size (23.1.2.6)</th></tr></thead><tbody><tr><td><code>xclang-&lt;version&gt;-&lt;host&gt;.tar.xz</code></td><td>the toolchain, one per host, every target in each</td><td>95 to 128 MB</td></tr><tr><td><code>libclang-&lt;version&gt;-&lt;host&gt;.tar.xz</code></td><td>clang&#39;s and LLVM&#39;s static libraries and headers, one per host (<a href="./../features/libclang">libclang</a>)</td><td>260 to 274 MB</td></tr><tr><td><code>libclang-&lt;version&gt;-&lt;host&gt;-asan.tar.xz</code></td><td>their ASan build, for Linux x64 and macOS arm64</td><td>191, 210 MB</td></tr><tr><td><code>llvm-option-inc-&lt;version&gt;.tar.xz</code></td><td>the option tables of clang, lld, llvm-lib and llvm-dlltool</td><td>175 KB</td></tr><tr><td><code>xclang-&lt;version&gt;.profdata</code></td><td>the PGO profile the release was built with</td><td>52 MB</td></tr><tr><td><code>SHA256SUMS</code></td><td>the sha256 of every other asset</td><td></td></tr></tbody></table><p>The hosts are <code>x86_64-unknown-linux-gnu</code>, <code>aarch64-unknown-linux-gnu</code>, <code>x86_64-w64-mingw32</code>, <code>aarch64-w64-mingw32</code>, <code>aarch64-apple-darwin</code> and <code>x86_64-apple-darwin</code>.</p><h2 id="checking-a-download" tabindex="-1">Checking a download <a class="header-anchor" href="#checking-a-download" aria-label="Permalink to &quot;Checking a download&quot;">​</a></h2><p><code>SHA256SUMS</code> is written by the workflow that drafts the release, from the files it uploads. To check what was downloaded against it:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> download</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 23.1.2.6</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clice-io/xclang</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SHA256SUMS</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;llvm-option-inc-*&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sha256sum</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ignore-missing</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SHA256SUMS</span></span></code></pre></div><p>The Bazel module checks every archive by the sha256 its <code>versions.bzl</code> pins, and CMake&#39;s <code>xclang.cmake</code> checks the toolchain against the release&#39;s <code>SHA256SUMS</code>. Both are as trustworthy as the release: GitHub releases are not yet immutable, so an archive and the <code>SHA256SUMS</code> beside it could in principle be replaced together. A pin in <code>versions.bzl</code>, or a digest recorded in a project of its own, is not affected by that. Immutable releases are <a href="./../design/roadmap#reproducibility">planned</a>.</p><h2 id="where-else-a-release-is-published" tabindex="-1">Where else a release is published <a class="header-anchor" href="#where-else-a-release-is-published" aria-label="Permalink to &quot;Where else a release is published&quot;">​</a></h2><ul><li><strong>conda</strong>: <a href="https://conda.clice.io" target="_blank" rel="noreferrer">conda.clice.io</a>, the <code>xclang</code> package per host and the noarch <code>llvm-option-inc</code>, made from the release&#39;s archives after it is published (<a href="./../guide/install">installing</a>).</li><li><strong>Bazel</strong>: <a href="https://bazel.clice.io" target="_blank" rel="noreferrer">bazel.clice.io</a>, the module of the release&#39;s tag, published once it builds and tests with the published archives (<a href="./../integrations/bazel">Bazel</a>).</li><li><strong>CMake</strong>: the tag itself, which FetchContent checks out (<a href="./../integrations/cmake#without-xclang-installed">CMake</a>).</li></ul><p>How a release is built and tested is in <a href="./../design/release-build">how a release is built</a>.</p>`,17)])])}const k=a(r,[["render",l]]);export{g as __pageData,k as default};
